from pathlib import Path
import re

needle='DEV-PRED-ASTRA-AUTONOMOUS-REVIEWER-FIRSTFAIL-20261005'
roots=[
    Path.home()/'.local/state/prediction-command-bus',
    Path.home()/'.local/share/prediction-command-bus',
    Path.home()/'.local/state/prediction-project-executor',
]
hits=[]
for root in roots:
    if not root.exists():
        continue
    for p in root.rglob('*'):
        if not p.is_file():
            continue
        try:
            if p.stat().st_size > 2_000_000:
                continue
            txt=p.read_text(encoding='utf-8',errors='replace')
        except Exception:
            continue
        if needle in txt:
            hits.append((p,txt))

print('RUNTIME_HITS='+str(len(hits)))
for p,txt in hits[:20]:
    print('FILE='+str(p))
    lines=txt.splitlines()
    selected=[]
    for i,line in enumerate(lines):
        if needle in line or re.search(r'(FAILED|FAILURES|AssertionError|E\s+|short test summary|Traceback|python rc=1)',line):
            start=max(0,i-3); end=min(len(lines),i+12)
            selected.extend(lines[start:end])
    if not selected:
        selected=lines[-160:]
    seen=set()
    print('EXCERPT_BEGIN')
    for line in selected[-220:]:
        if line in seen:
            continue
        seen.add(line)
        print(line[:2500])
    print('EXCERPT_END')
